    {
        // a[k] was set to k % 5 in the previous loop, so it lies in [0,4].
        let ak = a[k as usize];
        assert(ak >= 0 && ak <= 4);
        s += ak;
        k += 1;
    }
    // Now k == N, so s = sum_{i=1..N-1} a[i], and s <= 4*(N-1).
    assert(s <= 4 * (N - 1));

    // Store the result in sum[0].
    sum[0] = s;
    // Finally, s <= 4*(N-1) <= 4*N, as required.
    assert(sum[0] <= 4 * N);
